), insertados AS (
    INSERT INTO pna.aeropuertos (codigo_iata, nombre, ciudad, pais, id_origen, identificador, tipo, latitud, longitud, elevacion_pies, continente, region_iso, servicio_regular, codigo_icao, codigo_gps, codigo_local, sitio_web, wikipedia, palabras_clave, datos_origen_json, activo, fecha_desactivacion)
    SELECT d.codigo_iata, d.nombre, d.ciudad, d.pais, d.id_origen, d.identificador, d.tipo, d.latitud, d.longitud, d.elevacion_pies, d.continente, d.region_iso, d.servicio_regular, d.codigo_icao, d.codigo_gps, d.codigo_local, d.sitio_web, d.wikipedia, d.palabras_clave, d.datos_origen_json, d.activo, d.fecha_desactivacion
    FROM datos d
    WHERE NOT EXISTS (
        SELECT 1 FROM pna.aeropuertos a
        WHERE upper(btrim(a.codigo_iata)) = d.codigo_iata
    )
    ON CONFLICT (codigo_iata) DO NOTHING
    RETURNING aeropuerto_id
)
SELECT 8799 AS registros_del_archivo,
       count(*) AS aeropuertos_insertados,
       8799 - count(*) AS omitidos_por_iata_existente
FROM insertados;

COMMIT;
